args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?father ?fatherLabel ?deathPlaceLiteral ?deathPlaceResource ?deathPlaceResourceLabel WHERE {
  dbr:Hasan_ibn_Hasan dbp:father ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
  OPTIONAL { ?father dbp:deathPlace ?deathPlaceLiteral . }
  OPTIONAL { ?father dbo:deathPlace ?deathPlaceResource .
             OPTIONAL { ?deathPlaceResource rdfs:label ?deathPlaceResourceLabel . FILTER(lang(?deathPlaceResourceLabel) = 'en') } }
} LIMIT 25

